const photos={"compact": "data:image/webp;base64,", "sedan": "data:image/webp;base64,", "premium": "data:image/webp;base64,", "pickup": "data:image/webp;base64,", "sport": "data:image/webp;base64,", "crossover": "data:image/webp;base64,", "house": "data:image/webp;base64,"};
export function disalVehiclePhoto(p){
 if(p.administratorId!=="disal"||!(Number(p.creditCents)>0))return null;
 if(p.category==="Imóveis")return photos.house;
 const pool=p.creditCents<8000000?["compact","pickup","sport"]:p.creditCents<18000000?["sedan","pickup","sport","crossover"]:["premium","crossover"];
 const seed=String(p.family||'')+'|'+String(p.months||'');
 let hash=0;for(const c of seed)hash=(Math.imul(hash,31)+c.charCodeAt(0))>>>0;
 return photos[pool[hash%pool.length]];
}
